/* one 4KB page is eight 512 byte SD card blocks */
#define PAGE_SD_BLOCKS (PAGE_SIZE / 512)

/* User virtual address window reserved for shared pages.  It stops right
 * below the first page a user ELF is linked at: the image starts at 0x10000
 * but its headers live in the page before that. */
#define SHM_VA_BEGIN 0x1000lu
#define SHM_VA_END   0xf000lu

/* the image of a user program, headers included */
#define USER_CODE_BEGIN 0xf000lu
#define USER_CODE_END   0x14000lu

// returns pa
ptr_t alloc_user_page(uint8_t pin, PTE* pgtable)
{
    int i;
    for(i = 0; i < USER_PAGE_NUM; i++){
        if(user_page[i].valid == 0){
            break;
        }
    }

    ptr_t pa;
    if(i == USER_PAGE_NUM){
        /* physical memory is exhausted: swap somebody else out first */
        pa = selete_page();
        write_to_sd(pa);
        i = pa2num(pa);
    }
    else{
        pa = num2pa(i);
    }

    user_page[i].valid = 1;
    user_page[i].pin = pin;
    user_page[i].pgtable = pgtable;

    /* a fresh page must not leak the previous owner's data */
    memset((void*)pa2kva(pa), 0, PAGE_SIZE);
    return pa;
}

// baseAddr is pa
void free_user_page(ptr_t baseAddr)
{
    user_page[pa2num(baseAddr)].valid = 0;
}

